"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["77762"],{63130(e,n,t){t.r(n),t.d(n,{metadata:()=>i,default:()=>d,frontMatter:()=>r,contentTitle:()=>o,toc:()=>l,assets:()=>h});var i=JSON.parse('{"id":"nhcx/v1/concepts/pmjay-on-nhcx","title":"PMJAY on NHCX","description":"What the Ayushman Bharat scheme changes on the network, and the scheme rules a hospital system must follow.","source":"@site/docs/nhcx/v1/concepts/pmjay-on-nhcx.md","sourceDirName":"nhcx/v1/concepts","slug":"/nhcx/v1/concepts/pmjay-on-nhcx","permalink":"/docs/pr-49/docs/nhcx/v1/concepts/pmjay-on-nhcx","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1790289181000,"sidebarPosition":8,"frontMatter":{"title":"PMJAY on NHCX","sidebar_label":"PMJAY on NHCX","sidebar_position":8,"description":"What the Ayushman Bharat scheme changes on the network, and the scheme rules a hospital system must follow.","sidebar_class_name":"sidebar-icon sidebar-icon--shield-plus","source":"nhcx-package/docs/01-Overview/08-PMJAY on NHCX.md","generated":true,"covers":["nhcx.flow.pmjay-hospital-migration"]},"sidebar":"nhcx-v1-overview","previous":{"title":"Workflow Codes","permalink":"/docs/pr-49/docs/nhcx/v1/concepts/workflow-codes"},"next":{"title":"PMJAY use cases","permalink":"/docs/pr-49/docs/nhcx/v1/concepts/pmjay-use-cases"}}'),s=t(62540),a=t(43023);let r={title:"PMJAY on NHCX",sidebar_label:"PMJAY on NHCX",sidebar_position:8,description:"What the Ayushman Bharat scheme changes on the network, and the scheme rules a hospital system must follow.",sidebar_class_name:"sidebar-icon sidebar-icon--shield-plus",source:"nhcx-package/docs/01-Overview/08-PMJAY on NHCX.md",generated:!0,covers:["nhcx.flow.pmjay-hospital-migration"]},o="PMJAY on NHCX",h={},l=[{value:"The problem with a TMS-only workflow",id:"the-problem-with-a-tms-only-workflow",level:2},{value:"The change",id:"the-change",level:2},{value:"What this means for an empanelled hospital",id:"what-this-means-for-an-empanelled-hospital",level:2},{value:"Where PMJAY differs from a private insurer integration",id:"where-pmjay-differs-from-a-private-insurer-integration",level:2},{value:"PMJAY scheme rules",id:"pmjay-scheme-rules",level:2},{value:"The integrator journey",id:"the-integrator-journey",level:2}];function c(e){let n={a:"a",h1:"h1",h2:"h2",header:"header",li:"li",ol:"ol",p:"p",strong:"strong",ul:"ul",...(0,a.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(n.header,{children:(0,s.jsx)(n.h1,{id:"pmjay-on-nhcx",children:"PMJAY on NHCX"})}),"\n",(0,s.jsx)(n.p,{children:"Ayushman Bharat Pradhan Mantri Jan Arogya Yojana, known as PMJAY, was launched on 23 September 2018. It is the largest health assurance scheme in the world, providing a health cover of Rs. 5 lakh per family per year for secondary and tertiary care hospitalisation to over 10.74 crore poor and vulnerable families, roughly 50 crore beneficiaries, forming the bottom 40 percent of the population. It is fully funded by government, with the cost of implementation shared between the Centre and the states."}),"\n",(0,s.jsx)(n.p,{children:"Claim adjudication under PMJAY runs through three integrated systems: the Beneficiary Identification System (BIS), the Transaction Management System (TMS), and the Hospital Empanelment Module (HEM). The key decisions sit in TMS, taken at preauthorisation by the Preauthorisation Processing Doctor (PPD) and at settlement by the Claim Processing Doctor (CPD)."}),"\n",(0,s.jsx)(n.p,{children:"The previous chapters described how a claim moves between a Provider and a private insurer over NHCX. This chapter covers what changes when the Payer is PMJAY."}),"\n",(0,s.jsx)(n.h2,{id:"the-problem-with-a-tms-only-workflow",children:"The problem with a TMS-only workflow"}),"\n",(0,s.jsx)(n.p,{children:"PMJAY claims processing today depends on the TMS 2.0 Provider System, whether or not the hospital runs its own HMIS. That creates four difficulties."}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Duplication of data entry."})," The same case is keyed into the hospital HMIS and again into TMS, increasing administrative workload and the risk of errors."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Lack of interoperability."})," Beneficiary, clinical and claims data cannot move cleanly between systems."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Single-system dependency."})," Relying exclusively on one provider system limits scalability and operational flexibility."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Restricted innovation."})," System constraints leave little room for hospitals and technology partners to build around the workflow."]}),"\n"]}),"\n",(0,s.jsx)(n.h2,{id:"the-change",children:"The change"}),"\n",(0,s.jsx)(n.p,{children:"A hospital running an ABDM-enabled HMIS integrated with NHCX can operate PMJAY workflows entirely within its own system, with no mandatory portal usage. Claims move directly from the hospital system to the payer system over the exchange."}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"No mandatory TMS dependency."})," The PMJAY workflow lives inside the HMIS rather than beside it."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Single-source data capture."})," PMJAY data is recorded once in the HMIS and reused for claims processing, removing the re-entry and reconciliation described above."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Choice of system."})," Hospitals are no longer tied to one PMJAY processing system and can pick any ABDM-enabled HMIS."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Scale."})," HMIS-based integration handles higher transaction volumes more reliably than a portal-based workflow."]}),"\n"]}),"\n",(0,s.jsx)(n.h2,{id:"what-this-means-for-an-empanelled-hospital",children:"What this means for an empanelled hospital"}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"PMJAY becomes part of routine operations."})," Cases are handled inside the hospital's normal workflow rather than as a separate portal-driven activity, and are no longer exposed to portal downtime, access constraints or concurrent user limits."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Structured data enables automation."})," Preauthorisation and claim processing can be automated, cutting cost and turnaround, reducing manual error and improving data quality, which is the basic requirement for any AI model and for fraud control."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Audit and finance improve."})," All PMJAY clinical and financial records sit within hospital systems, simplifying audits, internal reviews and compliance, and claims data flows natively into hospital billing and accounting."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Training simplifies."})," Staff learn one system instead of managing separate roles and workflows across HMIS and TMS."]}),"\n",(0,s.jsx)(n.h2,{id:"where-pmjay-differs-from-a-private-insurer-integration",children:"Where PMJAY differs from a private insurer integration"}),"\n",(0,s.jsx)(n.p,{children:"Once NHCX integration is complete, an integrator can send claims to any private insurer. PMJAY is a national assurance programme, so it carries scheme-specific requirements on top. The endpoints themselves do not change. Four things do."}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"The InsurancePlan response carries the scheme configuration."})," PMJAY uses the InsurancePlan FHIR bundle heavily. It is configured at hospital level and holds the available specialties, package costs, standard treatment guidelines, questionnaires and the mandatory documents required at preauthorisation and claim. This configuration drives most of what follows, so fetching and storing it correctly is a precondition rather than a convenience."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Biometric authentication is mandatory."})," The scheme requires biometric verification of the beneficiary at registration, during treatment and at discharge. This is an additional API, outside the NHCX set, that a PMJAY integrator must implement."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Supporting information must be structured."})," Sending scanned documents is not sufficient. Clinical information must travel in ABDM-defined structured Health Information Types."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Document queries do not use the Communication API."})," When the PMJAY payer wants more documents or clarification on a preauthorisation or claim, it queries the case itself. The provider answers on the same preauthorisation or claim endpoint with the same bundle, distinguished only by the workflow code. The Communication API is still used, but for other things. Telling a hospital a case has breached its turnaround time, passing on a grievance, or announcing a change to the beneficiary's wallet or to a package rate. Also asking for extra information outside a formal query, and acknowledging an arbitration request. A hospital system must still be able to receive it."]}),"\n",(0,s.jsx)(n.p,{children:"Set against the flows in the NHCX Use Cases chapter, the picture is:"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Get Insurance Plan, Get Policy, Coverage Eligibility Check, Claim Submission, Payment Notice and Status Check"})," behave the same as on any NHCX integration."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Preauthorisation"})," behaves the same, except that mandatory biometric authentication of the beneficiary must be completed before it is submitted."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Communication Request"})," is not used for document queries, which travel on the preauthorisation and claim endpoints instead. It is used for turnaround-time alerts, grievances, wallet and policy updates, and arbitration acknowledgements. A private insurer does the opposite: its query is the Communication Request itself."]}),"\n"]}),"\n",(0,s.jsx)(n.h2,{id:"pmjay-scheme-rules",children:"PMJAY scheme rules"}),"\n",(0,s.jsx)(n.p,{children:"PMJAY runs on strict clinical and financial rules that a commercial insurer does not use. A hospital system has to follow them when it builds each request. In plain words:"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Packages, not line items."})," Every admission is paid as a fixed package covering the bed, nursing, consultations, procedures, medicines and standard follow-up."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Fully cashless."})," A hospital may not charge the patient anything for a covered treatment."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Approval first."})," Surgery in secondary and tertiary care needs a preauthorisation, and the claim must point to the approval."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Biometric checks."})," The patient's fingerprint, iris or face is checked at registration, at preauthorisation, at every visit of a repeating treatment, and at discharge. These checks use ABDM's biometric service, not NHCX."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Every stay ends one of four ways."})," The patient goes home, dies in hospital, leaves against medical advice, or is discharged against medical advice. The claim also records whether they left before, during or after surgery."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Leaving before surgery is finished."})," If the patient leaves against advice before or during surgery, the surgical package is cancelled. The hospital is paid a daily rate for the days of the stay instead, set by the type of bed. If the patient leaves after surgery, the surgical package is paid."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Death in hospital."})," The claim keeps the package for the care given, and must carry the time of death and a death summary."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Repeating treatments."})," Dialysis and chemotherapy are approved as a block of sessions. Sessions must be at least 24 hours apart, each needs a biometric check, and only checked sessions are paid."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Procedures not on the list."})," A surgery missing from the package list can be booked only for a planned admission, under the patient's specialty, on its own, and within the patient's remaining cover."]}),"\n"]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.a,{href:"/docs/nhcx/v1/concepts/pmjay-use-cases#scheme-rules-the-hmis-must-implement",children:"Scheme rules the HMIS must implement"}),", in PMJAY use cases, gives the codes, fields, tariffs and error codes behind each rule."]}),"\n",(0,s.jsx)(n.h2,{id:"the-integrator-journey",children:"The integrator journey"}),"\n",(0,s.jsx)(n.p,{children:"The route to a PMJAY integration runs in five stages."}),"\n",(0,s.jsxs)(n.ol,{children:["\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Get compliant for ABDM Milestone 1."})," Request access to the sandbox APIs, integrate against them, complete functional testing and the security audit (WASA), give the HTC demo, and go live for ABDM M1."]}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Register on the NHCX sandbox."})," Register using the ABDM Client ID, generate a participant ID, create the public and private key pair, and work through the NHCX documentation until the API flows are properly understood."]}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Build the integration."})," Test the flows against the NHCX dummy payer, implement every use case API including biometric authentication and structured data exchange, and test all cases internally rather than only the happy path."]}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Exit the sandbox."})," Run the internal demo covering interoperability and FHIR bundle validation, give the PMJAY team demo, complete WASA and the HTC demo, and submit the NHCX sandbox exit form."]}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Go live by mapping."})," After the participant is created and configured in production, the hospital raises a ticket. It carries the existing PMJAY hospital ID, the HEM ID used in TMS, and the new NHCX participant ID. NHA's operations team maps the two by hand. That mapping is the switch: preauthorisations and claims raised before it finish their life in TMS, and everything raised after it goes through the HMIS. For a while a hospital is running both, so this step is planned rather than flipped."]}),"\n"]}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Two practical notes. To begin the integration, the integrator shares the Participant ID, Client ID and Registry ID with the NHCX team for onboarding onto the PMJAY staging environment. The Registry ID is then used as the Provider ID on sandbox. On successful completion, the integrator receives production keys for NHCX, which also serve for processing private insurer claims."})]})}function d(e={}){let{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(c,{...e})}):c(e)}}}]);